import {readFileSync,writeFileSync,mkdirSync,realpathSync} from 'node:fs';
import {dispatch,loadPlan,verifySnapshot} from '/Users/ilyagulya/Projects/My/bend/evals/g24_distributed.mjs';
const [planPath,root,sha256,archive,envelopePath,destination]=process.argv.slice(2);
const envelope=JSON.parse(readFileSync(envelopePath,'utf8'));
mkdirSync(destination,{mode:0o700});
const out=realpathSync(destination);
const context={...envelope.context,repository:envelope.context.candidate.repository,out,distributed:loadPlan(planPath)};
const snapshot={path:root,sha256,archive,manifest:verifySnapshot(root,sha256)};
const results={},failures=[];let cancelled=false;
const cancel=()=>{cancelled=true;context.distributionCancelled=true;};
for(const signal of ['SIGINT','SIGTERM','SIGHUP'])process.on(signal,cancel);
for(const job of ['matrix-js','native','admission','host']){
 if(cancelled)break;
 console.log(JSON.stringify({job,status:'RUNNING'}));
 try{results[job]=await dispatch(context,snapshot,job);console.log(JSON.stringify({job,status:'PASS',transport:results[job].transport}));}
 catch(error){failures.push({job,error:String(error)});console.error(JSON.stringify({job,status:'FAIL',error:String(error)}));}
}
const report={schemaVersion:1,status:!cancelled&&failures.length===0&&Object.keys(results).length===4?'PASS_REMAINING_ONLY':'FAIL',scope:'Only four original previously unexecuted consumer targets. Original full C62 remains FAIL; qualification receipt is not rewritten and strict12/promotion are not authorized.',sourceCheckpoint:'457305e2',originalRunId:envelope.context.runId,snapshotSha256:sha256,results,failures,cancelled,compilerAccepted:false,fullCorrectnessClaim:false,performanceClaim:false};
writeFileSync(out+'/outcome.json',JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({status:report.status,report:out+'/outcome.json'}));
if(report.status!=='PASS_REMAINING_ONLY')process.exitCode=1;
